from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal
from typing import Optional


class PromotionExpiredError(Exception):
    def __init__(self, code: str):
        super().__init__(f"Promotion {code!r} has expired")
        self.code = code


@dataclass(frozen=True)
class Promotion:
    code: str
    percent_off: Decimal
    expires_at: datetime


# PROVISIONAL: product has not decided the expired-promotion behavior.
# Current choice: reject the order. Change only this function to alter policy.
def _handle_expired(promo: Promotion):
    raise PromotionExpiredError(promo.code)


def checkout_total(subtotal: Decimal, promo: Optional[Promotion], now: datetime) -> Decimal:
    if promo is None:
        return subtotal
    if now >= promo.expires_at:
        return _handle_expired(promo)
    return (subtotal * (Decimal(100) - promo.percent_off) / 100).quantize(Decimal("0.01"))
