cat > test_checkout.py <<'E'
from datetime import datetime, timedelta
from decimal import Decimal
import pytest
from checkout import Promotion, PromotionExpiredError, checkout_total

NOW = datetime(2026, 11, 22, 12, 0)
def promo(delta): return Promotion("SAVE10", Decimal(10), NOW + delta)

def test_no_promo():
    assert checkout_total(Decimal("50.00"), None, NOW) == Decimal("50.00")

def test_valid_promo_applies():
    assert checkout_total(Decimal("50.00"), promo(timedelta(days=1)), NOW) == Decimal("45.00")

# Provisional policy: expired promotion rejects the order.
def test_expired_promo_rejected():
    with pytest.raises(PromotionExpiredError):
        checkout_total(Decimal("50.00"), promo(-timedelta(seconds=1)), NOW)

def test_promo_expiring_exactly_now_is_expired():
    with pytest.raises(PromotionExpiredError):
        checkout_total(Decimal("50.00"), promo(timedelta(0)), NOW)
E
